<script setup lang="ts">
import {ref,onMounted,computed} from 'vue'
import {RefreshCw,Save,Globe2,ShieldCheck} from 'lucide-vue-next'
import {api,notify,date,type Row} from '../lib'
const props=defineProps<{resources:Row[]}>()
const emit=defineEmits<{changed:[]}>()
const data=ref<Row>({settings:{},countries:[]}),form=ref<Row>({}),busy=ref(false),error=ref(''),result=ref(''),testCountry=ref('PH'),importId=ref(''),search=ref('')
const availableResources=computed(()=>props.resources.filter(r=>r.vendor==='iproyal'))
const visible=computed(()=>data.value.countries.filter((r:Row)=>[r.code,r.name,r.currency].some(v=>String(v).toLowerCase().includes(search.value.toLowerCase()))))
async function load(){data.value=await api('/admin/country-pool');const s=data.value.settings;form.value={auth_type:s.auth_type,username:s.username,subuser_hash:s.subuser_hash,lifetime_seconds:s.lifetime_seconds,max_parallel:s.max_parallel,renewal_country:s.renewal_country,auto_sync:s.auto_sync,token:'',password:''}}
async function run(fn:()=>Promise<void>){if(busy.value)return;busy.value=true;error.value='';result.value='';try{await fn()}catch(e){error.value=(e as Error).message}finally{busy.value=false}}
async function save(){await run(async()=>{await api('/admin/country-pool','PUT',form.value);await load();notify('独立会话代理配置已保存');emit('changed')})}
async function importResource(){await run(async()=>{await api('/admin/country-pool','PUT',{import_resource_id:importId.value});await load();notify('已复制代理账号及现有粘性时长');emit('changed')})}
async function sync(){await run(async()=>{const r=await api('/admin/country-pool/sync','POST',{});await load();result.value=`已同步 ${r.countries} 个代理国家。`;emit('changed')})}
onMounted(()=>run(load))
</script>
<template>
 <div class="pool-summary stats-grid four"><article class="stat"><div class="stat-label">供应商</div><strong class="provider">IPRoyal</strong><span class="muted">住宅动态代理</span></article><article class="stat"><div class="stat-label">支持国家 / 地区</div><strong>{{data.settings.country_count||0}}</strong></article><article class="stat"><div class="stat-label">占用会话</div><strong>{{data.in_use||0}}<small>/ {{data.settings.max_parallel||20}}</small></strong></article><article class="stat"><div class="stat-label">最近同步</div><b>{{data.settings.synced_at?date(data.settings.synced_at):'尚未同步'}}</b><small class="muted">{{data.settings.ready?'账户配置完整':'等待配置账户'}}</small></article></div>
 <div v-if="error" class="alert danger" role="alert">{{error}}</div><div v-if="result" class="callout" role="status">{{result}}</div><div v-if="data.settings.last_error" class="alert danger">最近同步失败：{{data.settings.last_error}}。已保留上次成功的国家列表。</div>
 <div class="pool-layout"><section class="panel form-panel"><h2>连接与会话</h2><form @submit.prevent="save">
 <label>API Token<input v-model="form.token" type="password" autocomplete="new-password" :placeholder="data.settings.token_configured?'已配置，留空保留':'填写 IPRoyal API 令牌'" :disabled="busy"/></label>
 <label>代理账户认证<select v-model="form.auth_type"><option value="credentials">代理账号与密码</option><option value="subuser">子账户标识</option></select></label>
 <template v-if="form.auth_type==='credentials'"><div class="form-grid"><label>代理用户名<input v-model="form.username" autocomplete="off" maxlength="1000"/></label><label>代理密码<input v-model="form.password" type="password" autocomplete="new-password" :placeholder="data.settings.password_configured?'已配置，留空保留':'填写原始密码，不加国家或会话参数'"/></label></div></template>
 <label v-else>子账户标识<input v-model="form.subuser_hash" autocomplete="off" maxlength="1000"/></label>
 <div class="form-grid"><label>粘性会话有效期（秒）<input v-model.number="form.lifetime_seconds" type="number" min="60" max="86400" required/><small>分配后开始计时，重试不会延长。</small></label><label>最多占用会话<input v-model.number="form.max_parallel" type="number" min="1" max="100" required/></label><label>独立续费默认国家<select v-model="form.renewal_country"><option v-if="!data.countries.length" value="PH">菲律宾 · PH</option><option v-for="r in data.countries" :key="r.code" :value="r.code">{{r.name}} · {{r.code}}</option></select></label><label class="checkbox-label"><input type="checkbox" v-model="form.auto_sync"/>每天自动同步国家</label></div>
 <div class="form-footer"><button class="btn primary" :disabled="busy"><Save :size="16"/>保存配置</button><button type="button" class="btn secondary" :disabled="busy||!data.settings.token_configured" @click="run(async()=>{const r=await api('/admin/country-pool/test','POST',{});result=r.message+'，共 '+r.countries+' 个国家。'})"><ShieldCheck :size="16"/>测试已保存连接</button></div>
 </form><details v-if="availableResources.length" class="business-records"><summary>从手动代理复制 IPRoyal 账号</summary><p class="muted small">复制原始账号、密码和粘性时长；保存后不会改变手动代理。</p><label>已有代理<select v-model="importId"><option value="">请选择</option><option v-for="r in availableResources" :key="r.id" :value="r.id">{{r.name}}</option></select></label><button class="btn secondary" :disabled="busy||!importId" @click="importResource">复制账号和时长</button></details></section>
 <section class="panel form-panel"><h2>国家与连接测试</h2><p class="muted">每单生成独立粘性会话，办理和重试复用同一连接。此处测试不创建订单。</p><div class="actions"><button class="btn primary" :disabled="busy||!data.settings.token_configured" @click="sync"><RefreshCw :size="16" :class="{spinning:busy}"/>同步全部国家</button><a class="btn secondary" href="#/admin/regions"><Globe2 :size="16"/>管理订阅地区</a></div><label>测试国家<select v-model="testCountry"><option v-for="r in data.countries" :key="r.code" :value="r.code">{{r.name}} · {{r.code}}</option></select></label><button class="btn secondary" :disabled="busy||!data.settings.ready||!data.countries.length" @click="run(async()=>{const r=await api('/admin/country-pool/test-country','POST',{country:testCountry});result=r.message+'（'+r.country+'）'})">测试指定国家</button><p class="muted small">这里只更新供应商支持的国家，不增删订阅地区。支付国家按订阅地区的开放设置显示。</p><input v-model="search" placeholder="搜索已同步国家或币种" aria-label="搜索代理池国家"/><div class="pool-countries"><div v-for="r in visible" :key="r.code"><span>{{r.name}} <small>{{r.code}}</small></span><b>{{r.currency||'待配置币种'}}</b></div><p v-if="!visible.length" class="muted">{{data.countries.length?'没有匹配结果':'保存令牌后同步国家'}}</p></div></section></div>
</template>
<style scoped>
.pool-layout{display:grid;grid-template-columns:minmax(0,1.2fr) minmax(0,1fr);gap:20px}.pool-layout .form-panel{max-width:none;min-width:0}.pool-layout h2{margin-bottom:20px}.pool-summary .provider{font-size:28px}.pool-summary small{display:block;margin-top:8px}.pool-countries{max-height:380px;overflow:auto;margin-top:12px}.pool-countries>div{display:flex;justify-content:space-between;gap:12px;padding:10px 0;border-bottom:1px solid var(--line)}.pool-countries small{color:var(--muted)}.pool-layout .actions,.pool-layout .form-footer{flex-wrap:wrap}@media(max-width:1000px){.pool-layout{grid-template-columns:1fr}}
</style>
